To generate and use authentication tokens, we'll be using JSON Web Tokens (JWT). Here's an example of how to implement JWT authentication in a Flask backend.

Firstly, you need to install the required libraries:

```bash
pip install flask jwt
```

Now, let's create a simple Flask app with JWT authentication.

**app.py**

```python
from flask import Flask, request, jsonify
import jwt
from werkzeug.security import generate_password_hash, check_password_hash
from datetime import datetime, timedelta

app = Flask(__name__)
app.config['SECRET_KEY'] = 'super-secret'  # Change this to a random secret key
users = {
    "user1": generate_password_hash("password1"),
    "user2": generate_password_hash("password2")
}

def create_token(user):
    payload = {
        "user_id": user,
        "exp": datetime.utcnow() + timedelta(hours=1)
    }
    return jwt.encode(payload, app.config['SECRET_KEY'], algorithm='HS256')

def verify_token(token):
    try:
        payload = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
        return payload["user_id"]
    except jwt.ExpiredSignatureError:
        return None
    except jwt.InvalidTokenError:
        return None

@app.route("/login", methods=["POST"])
def login():
    username = request.json.get("username")
    password = request.json.get("password")

    for user in users.values():
        if check_password_hash(user, password):
            token = create_token(username)
            return jsonify({"token": token.decode('UTF-8')})

@app.route("/protected", methods=["GET"])
def protected():
    token = request.headers.get("Authorization")
    user_id = verify_token(token)

    if user_id is None:
        return jsonify({"message": "Token is invalid or has expired"}), 401

    # If the token is valid, we can proceed with the request
    return jsonify({"message": f"Hello, {user_id}"})

if __name__ == "__main__":
    app.run(debug=True)
```

